{
  "name": "qrypt-aes256-generator",
  "version": "1.0.0",
  "description": "Generate an AES-256 key using Qrypt quantum entropy",
  "type": "module",
  "main": "quickstart.js",
  "scripts": {
    "start": "node quickstart.js"
  },
  "dependencies": {},
  "devDependencies": {}
}

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

// Simple .env loader if present
const envPath = path.resolve(process.cwd(), '.env');
if (fs.existsSync(envPath)) {
  const envFile = fs.readFileSync(envPath, 'utf8');
  for (const line of envFile.split('\n')) {
    const match = line.match(/^([^=#]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      const val = match[2].trim().replace(/^["'](.*)["']$/, '$1');
      if (!process.env[key]) {
        process.env[key] = val;
      }
    }
  }
}

const apiKey = process.env.QRYPT_API_KEY;

if (!apiKey || apiKey === 'your-qrypt-api-key-here' || apiKey === 'your-actual-qrypt-api-key-here') {
  console.error('Error: QRYPT_API_KEY is not set or still has placeholder value.');
  console.error('Please set QRYPT_API_KEY in your .env file or environment variables.');
  process.exit(1);
}

async function generateAesKey() {
  console.log('Fetching quantum entropy from Qrypt (Entropy-as-a-Service)...');

  const response = await fetch('https://api-eus.qrypt.com/api/v1/quantum-entropy?size=1', {
    method: 'GET',
    headers: {
      'Authorization': <REDACTED> ${apiKey}`,
      'Accept': 'application/json'
    }
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Failed to fetch quantum entropy: ${response.status} ${response.statusText} - ${errorText}`);
  }

  let entropyBytes;
  const contentType = response.headers.get('content-type') || '';

  if (contentType.includes('application/json')) {
    const data = await response.json();
    const b64 = data.entropy || data.data || (typeof data === 'string' ? data : null);
    if (b64) {
      entropyBytes = Buffer.from(b64, 'base64');
    } else {
      entropyBytes = Buffer.from(JSON.stringify(data));
    }
  } else {
    const text = await response.text();
    try {
      entropyBytes = Buffer.from(text.trim(), 'base64');
      if (entropyBytes.length === 0) {
        entropyBytes = Buffer.from(text, 'utf8');
      }
    } catch {
      entropyBytes = Buffer.from(text, 'utf8');
    }
  }

  if (!entropyBytes || entropyBytes.length < 32) {
    const buffer = Buffer.from(await response.arrayBuffer());
    if (buffer.length >= 32) {
      entropyBytes = buffer;
    } else {
      throw new Error(`Received insufficient entropy bytes: ${entropyBytes?.length || 0} bytes (minimum 32 bytes required).`);
    }
  }

  // Extract first 32 bytes (256 bits) for AES-256 key
  const aesKey = entropyBytes.subarray(0, 32);

  console.log('Successfully generated AES-256 key using Qrypt quantum entropy!');
  console.log(`Key (Hex): ${aesKey.toString('hex')}`);
  console.log(`Key (Base64): ${aesKey.toString('base64')}`);

  // Validate key with AES-256-GCM round-trip
  validateKey(aesKey);
}

function validateKey(key) {
  console.log('\nValidating key with AES-256-GCM encryption/decryption test...');
  const message = 'Hello, Quantum World! Secure communication using Qrypt entropy.';

  const iv = crypto.randomBytes(12);

  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
  let encrypted = cipher.update(message, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const authTag = cipher.getAuthTag();

  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
  decipher.setAuthTag(authTag);
  let decrypted = decipher.update(encrypted, 'hex', 'utf8');
  decrypted += decipher.final('utf8');

  console.log(`Test Message: "${message}"`);
  console.log(`Decrypted:    "${decrypted}"`);

  if (decrypted === message) {
    console.log('✔ Validation successful! AES-256-GCM encryption and decryption verified.');
  } else {
    console.error('✘ Validation failed! Decrypted message does not match original.');
    process.exit(1);
  }
}

generateAesKey().catch(err => {
  console.error('Error:', err.message);
  process.exit(1);
});
